<script setup lang="ts">
import HelpHint from '@/components/ui/HelpHint.vue'
import { onMounted,onUnmounted, ref,watch,toRef } from 'vue'
import { useWorkflowStore } from '@/stores/workflows'
import { workflowKinds, workflowStatuses, type WorkflowKind, type WorkflowRunRequest,type WorkflowRun,type WorkflowPlan } from '@/types/workflow'
import { workflowStep } from '@/utils/workflow'
import type { CompressionOptions } from '@/stores/compression'
import CompressionSettingsPanel from '@/components/compression/CompressionSettingsPanel.vue'
import WorkflowRecoveryDialog from '@/components/workflows/WorkflowRecoveryDialog.vue'
import { normalizeWorkflowPlan,workflowParentDirectory } from '@/utils/workflow'
import WorkflowRunDialog from '@/components/workflows/WorkflowRunDialog.vue'
import WorkflowRunDetails from '@/components/workflows/WorkflowRunDetails.vue'
import Modal from '@/components/ui/Modal.vue'
import WorkspaceHeader from '@/components/ui/WorkspaceHeader.vue'
import WorkflowAutomationPanel from '@/components/workflows/WorkflowAutomationPanel.vue'
import { useWorkflowAutomationStore } from '@/stores/workflowAutomation'
const workflow = useWorkflowStore(),automation=useWorkflowAutomationStore()
const tab=toRef(workflow,'workspace'), expanded=ref(''), nextKind=ref<WorkflowKind>('compress'), runVisible=ref(false), deleteId=ref('')
const templatesVisible=ref(false),plansVisible=ref(false)
const recovery=ref<{run:WorkflowRun;from?:number}>(),initialRun=ref<Partial<WorkflowRunRequest>>()
onMounted(()=>workflow.initialize())
watch([runVisible,recovery],()=>automation.hold('workflow-review',runVisible.value||!!recovery.value),{immediate:true})
onUnmounted(()=>automation.hold('workflow-review',false))
async function openQueuedRun(id:string){await workflow.openRun(id);tab.value='runs'}
watch(()=>workflow.selectedRunId,id=>{if(recovery.value&&id!==recovery.value.run.id){recovery.value=undefined;tab.value='runs'}})
function openRecovery(from?:number){if(!workflow.selectedRun||workflow.busy)return;workflow.error='';workflow.resumeIssue=undefined;recovery.value={run:workflow.selectedRun,from}}
function freshLegacy(){const run=workflow.selectedRun,plan=workflow.plans.find(plan=>plan.id===run?.planId);if(!run||!plan||workflow.busy)return;workflow.draft=normalizeWorkflowPlan(plan);workflow.error='';initialRun.value={paths:[...run.inputs],outputDirectory:workflowParentDirectory(run.directory)};runVisible.value=true}
async function resume(plan:WorkflowPlan,request:WorkflowRunRequest,from:number){if(recovery.value)await workflow.resume(recovery.value.run.id,plan,request,from)}
function template(kind:'repack'|'dated'|'empty'){workflow.newPlan(kind);expanded.value='';tab.value='edit';templatesVisible.value=false}
function choose(id:string){workflow.choosePlan(id);expanded.value='';tab.value='edit';plansVisible.value=false}
function addStep(){if(workflow.draft.steps.length>=8)return;const step=workflowStep(nextKind.value);workflow.draft.steps.push(step);expanded.value=step.id}
function move(index:number,delta:number){const steps=workflow.draft.steps;[steps[index],steps[index+delta]]=[steps[index+delta],steps[index]]}
function updateSettings(index:number,value:CompressionOptions){const step=workflow.draft.steps[index];step.settings={...value,deleteAfter:false,fastPack:false};if(value.password)step.passwordRequired=true}
async function run(request:WorkflowRunRequest){const pending=workflow.start(request);await Promise.resolve();if(workflow.busy){runVisible.value=false;tab.value='runs'}await pending}
</script>
<template>
  <div class="module-page workflow-page custom-scrollbar" data-testid="workflow-page">
    <WorkspaceHeader title="工作流中心" description="按顺序使用上一步的实际产物；点击步骤展开配置。任一步失败或停止，后续步骤不会开始。方案只记住参数，密码在运行时填写。" icon="pi pi-sitemap">
      <button class="control" data-testid="workflow-plans-open" @click="plansVisible=true"><i class="pi pi-folder-open"/>我的方案<span class="module-count">{{ workflow.plans.length }}</span></button>
      <button class="control primary" data-testid="workflow-new-open" :disabled="workflow.busy" @click="templatesVisible=true"><i class="pi pi-plus"/>新建方案</button>
    <template #navigation><nav class="module-tabs" aria-label="工作流视图">
      <button :class="{active:tab==='edit'}" :aria-pressed="tab==='edit'" data-testid="workflow-edit-tab" @click="tab='edit'"><i class="pi pi-sitemap"/>方案步骤</button>
      <button :class="{active:tab==='runs'}" :aria-pressed="tab==='runs'" data-testid="workflow-runs-tab" @click="tab='runs'"><i class="pi pi-history"/>运行与结果<span v-if="workflow.runs.length" class="module-count">{{ workflow.runs.length }}</span></button>
      <button :class="{active:tab==='directory'}" :aria-pressed="tab==='directory'" data-testid="workflow-directory-tab" @click="tab='directory'"><i class="pi pi-bolt"/>自动化与队列</button>
    </nav></template></WorkspaceHeader>

    <p v-if="workflow.error" class="message failure" role="alert" data-testid="workflow-error">{{ workflow.error }}<button v-if="!workflow.plans.length && !workflow.busy" class="ml-3 underline" @click="workflow.initialize()">重新读取</button></p><p v-if="workflow.notice && tab!=='directory'" class="workflow-notice" role="status"><i class="pi pi-check-circle"/><span>{{ workflow.notice }}</span><button @click="workflow.notice=''" aria-label="关闭提示"><i class="pi pi-times"/></button></p><p v-if="workflow.saveError" class="message failure" role="alert">{{ workflow.saveError }}</p>
    <div v-if="workflow.busy" class="running-banner"><div class="min-w-0"><strong><i class="pi pi-spin pi-spinner mr-2"/>{{ workflow.stopRequested?'正在停止当前处理…':workflow.phase||'工作流正在运行' }}</strong><p class="muted">切换页面会继续处理，结果和日志保留在这里。<span v-if="workflow.proofProgress"> 已读取 {{ Math.round(workflow.proofProgress.bytes/1048576*10)/10 }} MiB · {{ workflow.proofProgress.files }} 个文件</span></p></div><button class="control" data-testid="workflow-stop" :disabled="workflow.stopRequested" @click="workflow.stop()">停止本次运行</button></div>
    <WorkflowAutomationPanel v-if="tab==='directory'" @open="openQueuedRun"/>
    <div v-else class="workspace"><main class="panel min-w-0">
        <div v-if="tab==='edit'" class="space-y-5"><div class="editor-heading"><label class="field flex-1 min-w-0">方案名称<input v-model="workflow.draft.name" maxlength="60" class="control w-full mt-2" data-testid="workflow-plan-name" :disabled="workflow.busy" placeholder="给这套流程起个名字"></label><div class="actions"><button class="control" data-testid="workflow-copy" :disabled="workflow.busy" @click="workflow.copyPlan()">复制</button><button class="control" data-testid="workflow-save" :disabled="workflow.busy || workflow.saving" @click="workflow.savePlan()"><i class="pi pi-save"/>{{ workflow.saving?'保存中…':'保存方案' }}</button><button class="control primary" data-testid="workflow-run-open" :disabled="workflow.busy || !workflow.draft.steps.length" @click="initialRun=undefined;runVisible=true"><i class="pi pi-play"/>运行</button></div></div>
        <article v-for="(step,index) in workflow.draft.steps" :key="step.id" class="editor-step"><div class="step-top"><button class="step-toggle" :data-workflow-step="index" :aria-expanded="expanded===step.id" @click="expanded=expanded===step.id?'':step.id"><span class="step-number">{{ index+1 }}</span><i :class="['pi',workflowKinds[step.kind].icon]"/><span class="min-w-0 text-left flex-1"><strong>{{ step.name }}</strong><small>{{ workflowKinds[step.kind].label }} · {{ index?'使用上一步产物':'使用本次来源' }}</small></span><i :class="expanded===step.id?'pi pi-chevron-up':'pi pi-chevron-down'"/></button><div class="step-tools"><button class="icon-button" :disabled="workflow.busy || index===0" aria-label="上移步骤" @click="move(index,-1)"><i class="pi pi-arrow-up"/></button><button class="icon-button" :disabled="workflow.busy || index===workflow.draft.steps.length-1" aria-label="下移步骤" @click="move(index,1)"><i class="pi pi-arrow-down"/></button><button class="icon-button" :disabled="workflow.busy" aria-label="移除步骤" @click="workflow.draft.steps.splice(index,1)"><i class="pi pi-times"/></button></div></div>
          <fieldset v-if="expanded===step.id" class="step-content space-y-4" :disabled="workflow.busy"><label class="field">步骤名称<input v-model="step.name" maxlength="60" class="control w-full mt-2" :data-workflow-step-name="index"></label><HelpHint :label="workflowKinds[step.kind].label+'说明'">{{ workflowKinds[step.kind].description }}</HelpHint><label v-if="step.kind==='filter'" class="field">保留的扩展名<input v-model="step.extensions" class="control w-full mt-2" data-testid="workflow-extensions" placeholder="例如 txt,md,pdf；留空选择全部文件"><span class="muted block mt-2">读取目录及子目录，筛选后直接交给下一步，不移动原文件。</span></label><p v-else-if="step.kind==='extract'" class="muted callout">来源密码和编码在运行时统一填写。每份归档解压到本次独立目录；后续打包会使用实际解压内容。</p><template v-else><label class="password-choice"><input v-model="step.passwordRequired" type="checkbox" :data-workflow-require-password="index" @change="!step.passwordRequired && (step.settings.password='')">每次运行时提供输出密码</label><p class="muted">归档名可用 <code>{name}</code> 来源名、<code>{date}</code> 日期、<code>{time}</code> 时间、<code>{step}</code> 步骤序号。</p><CompressionSettingsPanel :model-value="step.settings" :show-output-path="false" :allow-delete-after="false" :allow-single-file-formats="false" :allow-regular-file-formats="false" compact @update:model-value="updateSettings(index,$event)" /></template></fieldset>
        </article><div class="add-step"><select v-model="nextKind" class="control" :disabled="workflow.busy"><option v-for="(kind,key) in workflowKinds" :key="key" :value="key">{{ kind.label }}</option></select><button class="control" data-testid="workflow-add-step" :disabled="workflow.busy || workflow.draft.steps.length>=8" @click="addStep"><i class="pi pi-plus"/>添加步骤</button><span class="muted">{{ workflow.draft.steps.length }} / 8</span></div></div>
        <div v-else class="space-y-5"><label v-if="workflow.runs.length" class="field">选择运行记录<select v-model="workflow.selectedRunId" class="control w-full mt-2" data-testid="workflow-run-selector"><option v-for="record in workflow.runs" :key="record.id" :value="record.id">{{ record.name }} · {{ new Date(record.startedAt).toLocaleString() }} · {{ workflowStatuses[record.status] }}</option></select></label><WorkflowRunDetails v-if="workflow.selectedRun" :key="workflow.selectedRun.id" :run="workflow.selectedRun" :busy="workflow.busy" :can-restart="workflow.plans.some(plan=>plan.id===workflow.selectedRun?.planId)" @resume="openRecovery" @fresh="freshLegacy" @origin="workflow.openRun($event)"/><div v-else class="empty-state"><i class="pi pi-sitemap"/><h3>从一套小流程开始</h3><p class="muted">选择模板、调整参数后点击运行。各步产物和处理记录会留在这里。</p><button class="control mt-4" @click="tab='edit'">编辑方案</button></div></div>
      </main>
    </div>
    <Modal v-model:visible="templatesVisible" title="新建工作流方案" icon="pi pi-sitemap" size="md">
      <div class="template-list" data-testid="workflow-templates"><button class="template-choice" data-testid="workflow-template-repack" :disabled="workflow.busy" @click="template('repack')"><i class="pi pi-sync"/><span><strong>解压后重新打包</strong><small>解压 → 压缩，整理下载资料</small></span><i class="pi pi-angle-right"/></button><button class="template-choice" data-testid="workflow-template-dated" :disabled="workflow.busy" @click="template('dated')"><i class="pi pi-calendar"/><span><strong>按日期归档</strong><small>将来源打包，以日期命名，方便留存</small></span><i class="pi pi-angle-right"/></button><button class="template-choice" data-testid="workflow-template-new" :disabled="workflow.busy" @click="template('empty')"><i class="pi pi-plus"/><span><strong>从空白方案开始</strong><small>自己组合步骤，最多 8 个顺序步骤</small></span><i class="pi pi-angle-right"/></button></div>
    </Modal>
    <Modal v-model:visible="plansVisible" title="我的工作流方案" icon="pi pi-folder-open" size="md">
      <p v-if="workflow.loading" class="muted">正在读取…</p><div v-else-if="!workflow.plans.length" class="plans-empty"><i class="pi pi-sitemap"/><p>保存一套方案，下次直接使用。</p><button class="control primary" :disabled="workflow.busy" @click="plansVisible=false;templatesVisible=true">新建方案</button></div>
      <ul v-else class="saved-plans" data-testid="workflow-plan-list"><li v-for="plan in workflow.plans" :key="plan.id"><button class="list-item" :class="{selected:workflow.draft.id===plan.id}" :disabled="workflow.busy" :data-workflow-plan="plan.name" @click="choose(plan.id)"><strong>{{ plan.name }}</strong><span>{{ plan.steps.map(step=>workflowKinds[step.kind].label).join(' → ') }}</span></button><button class="icon-button" :disabled="workflow.busy" :aria-label="'删除方案 '+plan.name" @click="deleteId=plan.id;plansVisible=false"><i class="pi pi-trash"/></button></li></ul>
    </Modal>
    <WorkflowRunDialog v-if="runVisible" :plan="workflow.draft" :initial="initialRun" :error="workflow.error" @close="runVisible=false" @run="run"/>
    <WorkflowRecoveryDialog v-if="recovery" :key="recovery.run.id+String(recovery.from)" :run="recovery.run" :from="recovery.from" :busy="workflow.busy" :phase="workflow.phase" :progress="workflow.proofProgress" :error="workflow.error" :issue="workflow.resumeIssue" @run="resume" @close="!workflow.busy&&(recovery=undefined)" @stop="workflow.stop()"/>
    <Modal :visible="!!deleteId" title="删除这套方案？" size="sm" :show-footer="true" @update:visible="deleteId=''"><p class="muted">删除方案后，已有运行记录和文件仍然保留。</p><template #footer><button class="control" @click="deleteId=''">返回</button><button class="control" @click="workflow.deletePlan(deleteId);deleteId=''">删除方案</button></template></Modal>
  </div>
</template>
<style scoped>
.workflow-page{height:100%;overflow-y:auto;overflow-x:hidden;width:100%;margin:0 auto;padding:20px 24px;min-width:0;color:var(--text-content)}h2{font-size:13px;font-weight:900}.muted{font-size:11px;line-height:1.9;color:var(--text-muted);overflow-wrap:anywhere}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.control{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-width:0;border:1px solid var(--border-subtle);border-radius:10px;padding:9px 12px;font-size:12px;background:var(--bg-input);color:var(--text-content);transition:background .15s}.control:hover{border-color:var(--dynamic-accent)}.control.primary{background:var(--dynamic-accent);color:white}.control:disabled,.icon-button:disabled,.quiet:disabled{opacity:.4;cursor:default}.workspace{min-width:0}.panel{border:1px solid var(--border-subtle);border-radius:16px;padding:20px;background:var(--bg-card)}.list-item{display:block;width:100%;text-align:left;padding:13px 12px;border-radius:11px;border:1px solid transparent;min-width:0}.list-item.selected{border-color:color-mix(in srgb,var(--dynamic-accent) 45%,transparent);background:color-mix(in srgb,var(--dynamic-accent) 7%,transparent)}.list-item:hover{background:var(--bg-input)}.list-item strong{display:block;font-size:12px;font-weight:800;overflow-wrap:anywhere}.list-item span{display:block;font-size:10px;color:var(--text-muted);line-height:1.8;margin-top:4px;overflow-wrap:anywhere}.editor-heading{display:flex;gap:16px;align-items:flex-end;flex-wrap:wrap}.field{display:block;font-size:12px;font-weight:700}.editor-step{border:1px solid var(--border-subtle);border-radius:14px;background:var(--bg-input);min-width:0}.step-top{display:flex;align-items:center;gap:8px;padding-right:10px}.step-toggle{display:flex;align-items:center;gap:12px;min-width:0;flex:1;padding:16px}.step-toggle strong{display:block;font-size:13px;overflow-wrap:anywhere}.step-toggle small{display:block;color:var(--text-muted);font-size:10px;margin-top:5px}.step-number{display:grid;place-items:center;width:30px;height:30px;border-radius:10px;background:var(--bg-card);color:var(--dynamic-accent);font-weight:900;flex-shrink:0}.step-tools{display:flex;flex-shrink:0}.icon-button{width:28px;height:32px;border-radius:8px;color:var(--text-muted);font-size:11px}.icon-button:hover{background:var(--bg-card)}.step-content{padding:0 18px 18px;min-width:0}.password-choice{display:flex;align-items:center;gap:8px;font-size:12px}.callout{padding:12px;border-radius:10px;border:1px solid var(--border-subtle)}.add-step{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.running-banner{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 20px;border:1px solid var(--dynamic-accent);border-radius:16px;background:var(--bg-card);margin-bottom:20px;font-size:13px}.message{border:1px solid var(--border-subtle);background:var(--bg-card);border-radius:12px;font-size:12px;line-height:1.8;padding:12px 16px;margin-bottom:16px;overflow-wrap:anywhere}.failure{color:#ef4444}.empty-state{text-align:center;padding:70px 20px}.empty-state>i{font-size:34px;color:var(--dynamic-accent)}.empty-state h3{font-size:18px;font-weight:900;margin:20px 0 10px}.control:focus-visible,.icon-button:focus-visible,.step-toggle:focus-visible,.list-item:focus-visible{outline:2px solid var(--dynamic-accent);outline-offset:2px} .template-list{display:grid;gap:10px}.template-choice{display:flex;align-items:center;gap:14px;min-width:0;width:100%;padding:16px;border:1px solid var(--border-subtle);border-radius:13px;background:var(--bg-input);text-align:left;transition:border-color .16s,background .16s}.template-choice:hover:enabled{border-color:var(--dynamic-accent);background:color-mix(in srgb,var(--dynamic-accent) 5%,var(--bg-input))}.template-choice>i:first-child{display:grid;place-items:center;width:36px;height:36px;border-radius:11px;color:var(--dynamic-accent);background:var(--bg-card);flex-shrink:0}.template-choice>i:last-child{margin-left:auto;color:var(--text-muted)}.template-choice strong{display:block;font-size:13px;font-weight:800}.template-choice small{display:block;font-size:11px;color:var(--text-muted);line-height:1.8;margin-top:5px}.template-choice:disabled{opacity:.4}.saved-plans{display:grid;gap:8px}.saved-plans li{display:flex;align-items:center;gap:6px}.saved-plans .list-item{flex:1}.saved-plans .icon-button{flex-shrink:0}.plans-empty{text-align:center;display:grid;justify-items:center;gap:16px;padding:20px;font-size:12px;color:var(--text-muted)}.plans-empty>i{font-size:28px;color:var(--dynamic-accent)}
@container module (max-width:640px){.panel{padding:14px}.step-top{flex-wrap:wrap;padding-right:0}.step-tools{padding:0 10px 10px;margin-left:auto}.step-toggle{padding:12px;gap:8px}.step-content{padding:0 12px 14px}.running-banner{flex-wrap:wrap}}
.workflow-notice{display:flex;align-items:center;gap:8px;padding:9px 12px;border-radius:10px;background:color-mix(in srgb,var(--dynamic-accent) 6%,var(--bg-card));color:var(--text-muted);font-size:11px;line-height:1.8;margin-bottom:14px}.workflow-notice>i{color:var(--dynamic-accent)}.workflow-notice>span{min-width:0;flex:1;overflow-wrap:anywhere}.workflow-notice>button{padding:3px;font-size:10px}
@container module (max-width:520px){.editor-heading{display:block}.editor-heading>.actions{margin-top:12px}}
@media(max-width:800px){.workflow-page{padding:16px}.panel{border-radius:14px}.control{font-size:11px}}
</style>
